import {PRODUCTS,CATEGORIES,SECTORS,EPICS,CLIMATE,HIERARCHY,curve,rescue,impact,seed,remaining,quality,baseline,ingredientNeed,plan,simulate,propose,approve,recordOutcome,addAudit,invalidate,validateState,csv,uid,iso,hours} from './core.js';
const KEY='climaze-workspace-v1';let state,storageError='',view='overview',selectedBatch='',search='',catFilter='',whatIf=null,prefill=null,tourStep=-1;try{const stored=localStorage.getItem(KEY);state=stored?validateState(JSON.parse(stored)):seed();}catch(e){state=seed();storageError='Existing browser data could not be loaded. It has not been overwritten. Export the original backup below, then restore a valid backup or reset deliberately.';}
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(x,d=1)=>Number(x).toLocaleString('en-AU',{maximumFractionDigits:d}),fmt=t=>new Date(t).toLocaleString('en-AU',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}),local=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,16);},toISO=v=>new Date(v).toISOString();
const paths=[['overview','Overview'],['about','About ShelfShift'],['inventory','Batch inventory'],['twin','Expiry Twin'],['forecast','Demand forecast'],['planner','Stock planner'],['actions','Actions & approvals'],['outcomes','Outcomes & evidence'],['report','Impact report'],['handover','Project & backup']];
function toast(message,error=false){const el=$('toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6500);}
function commit(fn,message='Saved',changes=false){if(storageError)throw Error('Resolve the backup recovery notice before changing records.');const next=structuredClone(state);fn(next);if(changes)invalidate(next,message);validateState(next);try{localStorage.setItem(KEY,JSON.stringify(next));}catch(e){throw Error('Could not save in this browser. Export a backup before continuing.');}state=next;render();toast(message);}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function backup(){download('CliMaze_workspace_backup.json',JSON.stringify(state,null,2),'application/json');}
function productOpts(chosen){return Object.entries(CATEGORIES).map(([c,name])=>`<optgroup label="${esc(name)}">${Object.entries(PRODUCTS).filter(([,p])=>p.cat===c).map(([id,p])=>`<option value="${id}" ${chosen===id?'selected':''}>${esc(p.label)}</option>`).join('')}</optgroup>`).join('');}
function opts(map,chosen){return Object.entries(map).map(([id,p])=>`<option value="${id}" ${chosen===id?'selected':''}>${esc(p.label||p)}</option>`).join('');}
function batchOptions(chosen){return state.batches.map(b=>`<option value="${esc(b.id)}" ${b.id===chosen?'selected':''}>${esc(b.id)} · ${esc(PRODUCTS[b.product].label)} · ${num(remaining(state,b.id))} kg</option>`).join('');}
function field(label,name,value,type='number',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options){return `<label class="field">${label}<select name="${name}">${options}</select></label>`;}
function head(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">SHELFSHIFT · BY CLIMAZE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function tag(b){const q=quality(b,state.asOf);return q.blocked?`<span class="tag danger">Hold · ${esc(q.reason)}</span>`:`<span class="tag ${q.hours<24?'warn':''}">${q.hours<24?'Use soon':'Available'} · ${num(q.hours)} h</span>`;}
function stat(label,value,sub){return `<div class="kpi"><label>${label}</label><strong>${value}</strong><small>${sub}</small></div>`;}
const ACTION_LABEL={sell:'Sell / use first',use:'Use in preparation',donate:'Donate',transfer:'Transfer',inspect:'Inspect',discard:'Discard to compost'};
function climateLens(){const s=state.settings,m=impact(state),r=rescue(state),names={rotate:'freshness-first rotation',markdown:'markdown',transfer:'transfer'};return `<div class="grid climate"><section class="panel lens"><div class="panel-head"><h2>Climate lens</h2><span class="tag">COP31 · Zero Waste &amp; Methane</span></div><div class="lens-row"><div><label>At risk with ordinary rotation</label><strong>${num(m.baseRisk)} kg</strong></div><div class="arrow" aria-hidden="true">→</div><div><label>At risk with ${esc(names[m.best])}</label><strong>${num(m.bestRisk)} kg</strong></div></div><div class="lens-big"><strong>${num(m.avoided)} kg CO₂-e</strong><span>modelled landfill emissions avoided for ${esc(PRODUCTS[s.product].label.toLowerCase())} today, if the at-risk stock would otherwise be landfilled</span></div><p class="tiny">Factor ${num(m.factor,2)} kg CO₂-e per kg food waste to landfill (<a href="${CLIMATE.factorUrl}" target="_blank" rel="noopener">${esc(CLIMATE.factorSource)}</a>). Mostly methane from anaerobic decay. Modelled scenario, not a verified reduction; edit the factor under Actions.</p><div class="lens-foot"><span>Recorded donations <b>${num(m.donated)} kg</b></span><span>Recorded discard <b>${num(m.discarded)} kg</b> · ${num(m.discardEmissions)} kg CO₂-e if landfilled</span></div></section><section class="panel"><div class="panel-head"><h2>Rescue ladder</h2><a class="muted" href="#actions">Actions ↗</a></div><p class="muted">Next best action for each at-risk batch, ranked by the food recovery hierarchy.</p><div class="ladder">${HIERARCHY.map(h=>`<span class="rung ${h[0]}" title="${esc(h[2])}">${esc(h[1])}</span>`).join('<span aria-hidden="true">›</span>')}</div>${r.length?r.map((x,i)=>`<div class="rescue ${x.tier}"><div><strong>${esc(x.batchId)} · ${esc(ACTION_LABEL[x.action])} ${num(x.kg)} kg</strong><p>${esc(x.why)}</p></div><button class="secondary small" data-do="prefill" data-i="${i}">Prefill proposal</button></div>`).join(''):'<div class="empty">No batch is at risk in the current plan.</div>'}</section></div>`;}
function chart(b){const c=curve(b,state.asOf,whatIf??undefined),end=Math.max(c.projection[1].t,c.limit,c.now+6*36e5),W=600,H=210,L=36,R=26,T=14,B=30,x=t=>L+(t-c.start)/(end-c.start)*(W-L-R),y=p=>T+(100-p)/100*(H-T-B),pts=a=>a.map(p=>`${x(p.t).toFixed(1)},${y(p.pct).toFixed(1)}`).join(' '),dayTicks=[];for(let t=c.start;t<=end;t+=24*36e5)dayTicks.push(t);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Estimated quality remaining for ${esc(b.id)}: ${num(c.hours)} hours"><rect x="${L}" y="${y(25)}" width="${W-L-R}" height="${y(0)-y(25)}" class="zone"/>${[0,50,100].map(p=>`<line x1="${L}" x2="${W-R}" y1="${y(p)}" y2="${y(p)}" class="grid-line"/><text x="${L-6}" y="${y(p)+4}" text-anchor="end">${p}%</text>`).join('')}${dayTicks.map((t,i)=>`<text x="${x(t)}" y="${H-10}" text-anchor="middle">${i?'+'+i*24+' h':'Receipt'}</text>`).join('')}<line x1="${x(c.limit)}" x2="${x(c.limit)}" y1="${T}" y2="${H-B}" class="limit"/><text x="${x(c.limit)-4}" y="${T+10}" text-anchor="end" class="limit-label">Date limit</text><line x1="${x(c.now)}" x2="${x(c.now)}" y1="${T}" y2="${H-B}" class="now"/><text x="${x(c.now)+4}" y="${T+10}" class="now-label">Now</text><polyline points="${pts(c.points)}" class="hist"/><polyline points="${pts(c.projection)}" class="proj"/></svg><div class="legend"><span class="k hist"></span>Recorded history <span class="k proj"></span>Projection at ${whatIf??PRODUCTS[b.product].ref} °C <span class="k zone"></span>Use-soon zone</div>`;}
function twinLive(b){const q=quality(b,state.asOf,whatIf??undefined),base=quality(b,state.asOf),ref=PRODUCTS[b.product].ref,t=whatIf??ref,delta=q.hours-base.hours;return `<div class="whatif"><label class="field"><span>What if it is stored at <b>${t} °C</b> from now?</span><input id="whatif" type="range" min="0" max="30" step="1" value="${t}" aria-label="Future storage temperature in degrees Celsius"></label><div class="whatif-out"><strong>${q.blocked?'Review needed':num(q.hours)+' h'}</strong><span class="${delta<-0.05?'bad':delta>0.05?'good':''}">${Math.abs(delta)<0.05?'Reference storage':`${delta>0?'+':''}${num(delta)} h vs ${ref} °C`}${q.capped&&!q.blocked?' · capped by date limit':''}</span></div></div>${chart(b)}`;}
const TOUR=[['overview','1 · The problem, in one screen','Two strawberry batches share the same date label. The Climate lens shows how much would be wasted if we rotate by receipt order, and what freshness-first planning saves in CO₂-e.'],['twin','2 · Read the batch, not the date','ST-B sat in a 22 °C loading bay. Its Expiry Twin curve drops faster. Drag the what-if slider to see how storage temperature changes the window.'],['forecast','3 · Know the demand','A seven-day baseline, or covers × recipe ÷ yield for hospitality and production, sets the requirement.'],['planner','4 · Plan with stock that will last','Allocation uses the shortest quality window first, counts only carryover that survives, and orders only what is needed.'],['actions','5 · Compare, then decide','Scenarios show kg at risk of waste. The best option is highlighted. Propose an action; a reviewer must approve it against current data.'],['outcomes','6 · Evidence, not claims','Record what actually happened with a reference. Modelled savings and recorded outcomes are never mixed.']];
function tour(){const el=$('tour');if(!el)return;if(tourStep<0){el.hidden=true;el.innerHTML='';return;}const [,title,text]=TOUR[tourStep];el.hidden=false;el.innerHTML=`<div class="tour-head"><span class="eyebrow">GUIDED DEMO · ${tourStep+1}/${TOUR.length}</span><button class="link" data-tour="close" aria-label="Close guided demo">✕</button></div><strong>${esc(title)}</strong><p>${esc(text)}</p><div class="tour-dots">${TOUR.map((_,i)=>`<span class="${i===tourStep?'on':''}"></span>`).join('')}</div><div class="actions"><button class="secondary small" data-tour="back" ${tourStep?'':'disabled'}>Back</button><button class="primary small" data-tour="next">${tourStep===TOUR.length-1?'Finish':'Next'}</button></div>`;}
function goTour(i){tourStep=i>=0&&i<TOUR.length?i:-1;tour();if(tourStep>=0){if(location.hash!=='#'+TOUR[i][0])location.hash=TOUR[i][0];else render();}}
const SDGS=[['2','Zero Hunger','Safe surplus is routed to people first through the Feed people rung of the Rescue ladder.'],['12.3','Halve food waste','Target 12.3: halve per-capita food waste at retail and consumer level and cut losses along supply chains by 2030.'],['12.5','Reduce waste generation','Prevention before recovery, and recovery before landfill, in every recommendation.'],['13','Climate Action','Less food in landfill means less methane, a short-lived but powerful greenhouse gas.']];
const TEAM=[['Madhumitha Challa','Team lead','Product, demand and stock planning, integration and pitch','madhumithachalla'],['Abhishek Prabhu','Expiry Twin','Smart cold-chain Expiry Twin, data and modelling','AbhishekPrabhu1459'],['Vijayaraja Vaikunth','Prototype engineering','Prototype intelligence and data pipeline','vijayaraja12'],['Shyam Rangasamy Sundaraj','AI review','AI architecture, evaluation and risk','shyamrangasamyaus2024-coder'],['Nithilan','Policy & impact','Policy, stakeholders, equity and impact','']];
const VIDEOS=[['MDxd4dBMjvw','What is COP31?'],['OmIAhvP4d5U','Antalya hosts COP31'],['LggVYnUj990','COP31 Presidency: From Baku to Antalya']];
const SDG_COLORS={'2':'#DDA63A','12.3':'#BF8B2E','12.5':'#BF8B2E','13':'#3F7E44'};
function teamCards(){return `<div class="team">${TEAM.map(m=>`<div class="member"><span class="avatar" aria-hidden="true">${esc(m[0].split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div><strong>${esc(m[0])}</strong><span class="role">${esc(m[1])}</span><span>${esc(m[2])}</span>${m[3]?`<a href="https://github.com/${esc(m[3])}" target="_blank" rel="noopener">github.com/${esc(m[3])}</a>`:''}</div></div>`).join('')}</div>`;}
function goalsBand(){return `<section class="goals-band" aria-label="COP31 and UN Sustainable Development Goals"><div class="gb-cop"><span class="gb-label">COP31 · ANTALYA, TÜRKIYE · 9–20 NOV 2026</span><strong>Zero Waste &amp; Methane Reduction</strong><span>Australia presides over negotiations · Pre-COP in the Pacific</span></div><div class="gb-sdgs"><span class="gb-label">UN SUSTAINABLE DEVELOPMENT GOALS</span><div>${SDGS.map(g=>`<a class="sdg-chip" style="--c:${SDG_COLORS[g[0]]}" href="#about" title="${esc(g[2])}"><b>${g[0]}</b>${esc(g[1])}</a>`).join('')}</div></div></section>`;}
function about(){return head('Why ShelfShift exists.','ShelfShift is a product by team CliMaze for the Climate Hack-tion COP31 challenge: Zero Waste &amp; Methane Reduction.',`<a class="primary" href="#overview">Open the workspace ↗</a>`)+`<section class="panel about-brand"><img src="climaze-wordmark.svg" alt="CliMaze" width="230" height="57"><p>ShelfShift is designed, built and owned by team <b>CliMaze</b>: five Monash students tackling food waste and methane for COP31.</p></section>${goalsBand()}<section class="panel hero-about"><span class="tag">THE PROBLEM</span><h2>Same date label. Very different food.</h2><p>Food businesses rotate perishables by the date printed on the label. Two crates with the same date can have very different lives left if one sat in a warm loading bay. The label cannot tell them apart, so the wrong crate is used first, the right one is found too late, and good food goes to landfill, where it decays into methane.</p><div class="about-stats"><div><strong>7.6 Mt</strong><span>food wasted in Australia each year</span></div><div><strong>A$36.6 bn</strong><span>annual cost to the economy</span></div><div><strong>~3%</strong><span>of Australia's greenhouse-gas emissions</span></div><div><strong>2030</strong><span>national target to halve food waste</span></div></div><p class="tiny">Source: DCCEEW, <a href="https://www.dcceew.gov.au/environment/protection/waste/food-waste" target="_blank" rel="noopener">Reducing Australia's food waste</a>. Globally, food loss and waste is linked to 8–10% of greenhouse-gas emissions (<a href="https://www.unep.org/resources/publication/food-waste-index-report-2024" target="_blank" rel="noopener">UNEP Food Waste Index 2024</a>).</p></section><div class="grid equal"><section class="panel"><h2>What we are trying to solve</h2><div class="flow-row"><span class="step">1</span><div><strong>Invisible freshness</strong><p>Temperature history changes how long food really lasts, but nobody sees it at the batch level.</p></div></div><div class="flow-row"><span class="step">2</span><div><strong>Planning without freshness</strong><p>Orders and preparation are planned on quantity alone, so stock that will not last is counted as available.</p></div></div><div class="flow-row"><span class="step">3</span><div><strong>Surplus found too late</strong><p>At-risk stock is noticed when it can no longer be sold or donated, so it is binned.</p></div></div><div class="flow-row"><span class="step">4</span><div><strong>Impact claims without evidence</strong><p>Savings are often estimated loosely, which erodes trust. Recorded outcomes and modelled estimates get mixed up.</p></div></div></section><section class="panel"><h2>Product goals</h2><div class="goal"><b>Prevent first</b><p>Use the batch that will expire first, plan orders on stock that will actually last, and stop waste before it exists.</p></div><div class="goal"><b>Read the batch, not the date</b><p>An Expiry Twin per batch turns temperature history into an estimated quality window, never extending the printed date.</p></div><div class="goal"><b>Rescue what is left</b><p>Rank every at-risk batch by the food recovery hierarchy: prevent, feed people, check, recover. Never landfill.</p></div><div class="goal"><b>Measure honestly</b><p>Keep recorded outcomes separate from modelled CO₂-e, with cited factors and staff approval for every action.</p></div><div class="goal"><b>Fit real businesses</b><p>One workflow for retail, hospitality and food production. Runs in any browser, with no install or API key.</p></div></section></div><section class="panel space"><div class="panel-head"><h2>COP31 alignment</h2><span class="tag">Build for 2035</span></div><p>COP31 takes place in Antalya, Türkiye, from 9 to 20 November 2026, with Australia as President of Negotiations and Pre-COP events in the Pacific. The Presidency frames 2026 around implementation: turning commitments into practical outcomes. ShelfShift addresses the <b>Zero Waste &amp; Methane Reduction</b> priority with a tool a food business can use today, and an impact measure it can verify tomorrow.</p><h3 class="space">Watch: COP31 explained</h3><div class="videos">${VIDEOS.map(v=>`<figure class="video"><div class="frame"><iframe src="https://www.youtube-nocookie.com/embed/${v[0]}" title="${esc(v[1])}" loading="lazy" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><figcaption>${esc(v[1])} · <a href="https://www.youtube.com/watch?v=${v[0]}" target="_blank" rel="noopener">Watch on YouTube ↗</a></figcaption></figure>`).join('')}</div><p class="tiny">Sources: <a href="https://unfccc.int/cop31" target="_blank" rel="noopener">UNFCCC COP31</a> · <a href="https://www.dcceew.gov.au/climate-change/international-climate-action/unfccc-cop/cop31" target="_blank" rel="noopener">Australian Government COP31</a> · <a href="https://www.globalmethanepledge.org/" target="_blank" rel="noopener">Global Methane Pledge</a></p></section><section class="panel space"><h2>UN Sustainable Development Goals</h2><div class="sdgs">${SDGS.map(g=>`<div class="sdg" style="--c:${SDG_COLORS[g[0]]}"><span>SDG ${g[0]}</span><strong>${g[1]}</strong><p>${g[2]}</p></div>`).join('')}</div><p class="tiny">See the <a href="https://sdgs.un.org/goals/goal12" target="_blank" rel="noopener">UN SDG 12 targets</a>.</p></section><section class="panel space"><div class="panel-head"><h2>Team CliMaze</h2><span class="tag">Owners of ShelfShift</span></div>${teamCards()}<p class="tiny">Built for Climate Hack-tion, an EU-funded hackathon for students in Australia, New Zealand, the Pacific Islands and the EU.</p></section>`;}
function reportData(){const s=state.settings,h=24+s.needIn,rows=state.batches.map(b=>({b,q:quality(b,state.asOf),left:remaining(state,b.id)})),risk=r=>!r.q.blocked&&r.q.hours<h,cats=Object.entries(CATEGORIES).map(([c,name])=>{const rs=rows.filter(r=>PRODUCTS[r.b.product].cat===c);return {name,batches:rs.length,onHand:rs.reduce((v,r)=>v+r.left,0),atRisk:rs.filter(risk).reduce((v,r)=>v+r.left,0),held:rs.filter(r=>r.q.blocked).reduce((v,r)=>v+r.left,0)};}).filter(c=>c.batches),total=k=>state.outcomes.filter(o=>k.includes(o.action)).reduce((v,o)=>v+o.kg,0);return {s,h,rows,cats,m:impact(state),rescue:rescue(state),sims:['baseline','rotate','markdown','transfer'].map(m=>simulate(state,m)),onHand:rows.reduce((v,r)=>v+r.left,0),atRisk:rows.filter(risk).reduce((v,r)=>v+r.left,0),held:rows.filter(r=>r.q.blocked).length,rec:{sold:total(['sell','use']),donated:total(['donate']),transferred:total(['transfer']),discarded:total(['discard'])}};}
function reportBody(){const d=reportData(),f=d.s.factor,names={baseline:'Ordinary rotation',rotate:'Earliest quality first',markdown:'Markdown',transfer:'Transfer'},t=(head,rows,nums)=>`<div class="table-wrap"><table><thead><tr>${head.map((x,i)=>`<th class="${nums.includes(i)?'numeric':''}">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((x,i)=>`<td class="${nums.includes(i)?'numeric':''}">${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}" class="empty">None recorded.</td></tr>`}</tbody></table></div>`;return `<article class="report"><header class="report-head"><div><div class="eyebrow">SHELFSHIFT · BY CLIMAZE</div><h2>Food waste &amp; methane impact report</h2><p class="muted">Model clock ${esc(fmt(state.asOf))} · generated ${esc(new Date().toLocaleString('en-AU'))} · ${esc(SECTORS[d.s.sector])} setting · COP31 priority: Zero Waste &amp; Methane Reduction</p></div></header><section><h3>1. Summary</h3><div class="kpis">${stat('Stock on hand',num(d.onHand)+' kg',`${state.batches.length} batches · ${d.cats.length} categories`)}${stat('At risk of waste',num(d.atRisk)+' kg',`Quality window ends within ${num(d.h)} h`)}${stat('Landfill-equivalent risk',num(d.atRisk*f)+' kg CO₂-e','If the at-risk stock were landfilled')}${stat('Modelled avoidable',num(d.m.avoided)+' kg CO₂-e',`${esc(PRODUCTS[d.s.product].label)}: ${num(d.m.baseRisk)} → ${num(d.m.bestRisk)} kg at risk`)}</div></section><section><h3>2. Waste risk by category</h3>${t(['Category','Batches','On hand (kg)','At risk (kg)','Held (kg)','CO₂-e if landfilled (kg)'],d.cats.map(c=>[esc(c.name),c.batches,num(c.onHand),num(c.atRisk),num(c.held),num(c.atRisk*f)]),[1,2,3,4,5])}</section><section><h3>3. Recommended rescue actions</h3>${t(['Batch','Product','Tier','Action','kg','Hours left'],d.rescue.map(r=>[esc(r.batchId),esc(PRODUCTS[r.product].label),esc(HIERARCHY.find(x=>x[0]===r.tier)[1]),esc(ACTION_LABEL[r.action]),num(r.kg),num(r.hours)]),[4,5])}<p class="muted">Ranked by the food recovery hierarchy: prevent, feed people, check, recover. Every action still needs staff approval.</p></section><section><h3>4. Scenario comparison · ${esc(PRODUCTS[d.s.product].label)}</h3>${t(['Scenario','At risk (kg)','Sold / used (kg)','Transferred (kg)','Sales value (A$)','CO₂-e vs ordinary (kg)'],d.sims.map(r=>[names[r.mode],num(r.atRisk),num(r.sold),num(r.transferred),num(r.revenue,2),r.mode==='baseline'?'Reference':'−'+num(Math.max(0,d.sims[0].atRisk-r.atRisk)*f)]),[1,2,3,4,5])}</section><section><h3>5. Recorded outcomes</h3><div class="kpis">${stat('Sold / used',num(d.rec.sold)+' kg','Recorded with evidence')}${stat('Donated',num(d.rec.donated)+' kg','Recorded with evidence')}${stat('Transferred',num(d.rec.transferred)+' kg','Destination use not verified')}${stat('Discarded',num(d.rec.discarded)+' kg',num(d.rec.discarded*f)+' kg CO₂-e if landfilled')}</div>${t(['Recorded','Batch','Action','kg','Evidence'],state.outcomes.slice().reverse().map(o=>[esc(fmt(o.at)),esc(o.batchId),esc(o.action),num(o.kg),esc(o.evidence)]),[3])}</section><section><h3>6. Method, boundaries and sources</h3><ul class="report-notes"><li>Quality windows use an illustrative Q10 = 2 effective-age model from each batch's temperature history and never extend the printed date limit. They are not food-safety assessments.</li><li>"At risk" means usable stock whose estimated quality window ends before the next need-by time (24 h + ${num(d.s.needIn)} h).</li><li>CO₂-e uses ${num(f,2)} kg CO₂-e per kg of food waste to landfill (${esc(CLIMATE.factorSource)}). Modelled figures are not verified reductions. Recorded outcomes receive no avoided-emissions credit.</li><li>Starter records are synthetic demonstration data.</li></ul><p class="tiny">Sources: <a href="${CLIMATE.factorUrl}">NGA Factors 2023</a> · <a href="https://www.dcceew.gov.au/environment/protection/waste/food-waste">DCCEEW, Reducing Australia's food waste</a> · <a href="https://www.unep.org/resources/publication/food-waste-index-report-2024">UNEP Food Waste Index 2024</a> · <a href="https://sdgs.un.org/goals/goal12">UN SDG 12</a></p></section></article>`;}
function reportDocument(){const css=[...document.styleSheets].map(sh=>{try{return [...sh.cssRules].map(r=>r.cssText).join('\n')}catch{return ''}}).join('\n');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ShelfShift impact report</title><style>${css}body{padding:24px;zoom:1}</style></head><body>${reportBody()}</body></html>`;}
function report(){return head('Impact report','A shareable summary of stock, waste risk, climate impact and recorded outcomes. Print it, save it as PDF or download it.',`<div class="actions report-actions"><button class="primary" data-do="print-report">Print / save as PDF</button><button class="secondary" data-do="download-report">Download report (.html)</button></div>`)+`<section class="panel">${reportBody()}</section>`;}
function overview(){const p=plan(state),all=state.batches.reduce((v,b)=>v+remaining(state,b.id),0),held=state.batches.filter(b=>quality(b,state.asOf).blocked).length;return head('Your food, planned ahead.','One workspace for demand, batch freshness and the next practical action.',`<a class="primary" href="#planner">Open stock planner ↗</a>`)+`<div class="banner"><div><strong>Demand planning meets the Expiry Twin</strong><p>Madhumitha’s retail, hospitality and production planning + Abhishek’s temperature-history concept. Tackling COP31's Zero Waste &amp; Methane Reduction priority.</p></div><a class="tag" href="#about">Why ShelfShift? ↗</a></div>${goalsBand()}<div class="kpis">${stat('On-hand stock',num(all)+' kg','Across all products')}${stat('Needs earlier action',num(p.review)+' kg',PRODUCTS[state.settings.product].label+' · selected plan')}${stat('Next replenishment',num(p.order)+' kg',SECTORS[state.settings.sector]+' · next horizon')}${stat('Batches on hold',held,'Require a staff data or quality review')}</div>${climateLens()}<div class="grid"><section class="panel"><div class="panel-head"><h2>Freshness watch</h2><a class="muted" href="#inventory">All ${state.batches.length} batches ↗</a></div>${batchTable(state.batches.slice().sort((a,b)=>quality(a,state.asOf).hours-quality(b,state.asOf).hours).slice(0,6))}</section><section class="panel"><h2>Today's planning loop</h2><div class="flow-row"><span class="step">1</span><div><strong>Check the requirement</strong><p>Forecast sales, meal ingredients or production inputs.</p></div></div><div class="flow-row"><span class="step">2</span><div><strong>Use the right batch first</strong><p>Account for quality windows and temperature history.</p></div></div><div class="flow-row"><span class="step">3</span><div><strong>Review, then record</strong><p>Approve a decision and capture what actually happened.</p></div></div><div class="note">Model clock: ${esc(fmt(state.asOf))}. Starter records are synthetic. Adjust the clock under Project &amp; backup.</div></section></div><div class="grid equal"><section class="panel"><h2>Recent decisions</h2>${state.decisions.length?state.decisions.slice(0,3).map(d=>`<div class="flow-row"><span class="step">↗</span><div><strong>${esc(d.batchId)} · ${esc(d.action)}</strong><p>${num(d.kg)} kg · ${esc(d.status)}${d.revision!==state.revision?' · inputs changed':''}</p></div></div>`).join(''):'<div class="empty">Start with a batch and propose your first action.</div>'}</section><section class="panel"><h2>Built for three business settings</h2><div class="credit"><strong>Retail</strong><div class="muted">Sell-through, stock rotation and purchase planning.</div></div><div class="credit"><strong>Hospitality</strong><div class="muted">Covers, recipes and ingredient preparation.</div></div><div class="credit"><strong>Food production</strong><div class="muted">Output targets, yields and raw-material requirements.</div></div></section></div><section class="panel meet space"><div class="panel-head"><h2><img src="climaze-logo.svg" alt="" width="28" height="28"> Meet team CliMaze</h2><a class="muted" href="#about">About ↗</a></div>${teamCards()}</section>`;}
function batchTable(batches){return `<div class="table-wrap"><table><thead><tr><th>Batch / product</th><th class="numeric">Remaining</th><th>Quality window</th><th></th></tr></thead><tbody>${batches.map(b=>`<tr><td><div class="batch-id">${esc(b.id)}</div><div class="tiny">${esc(PRODUCTS[b.product].label)} · ${esc(CATEGORIES[PRODUCTS[b.product].cat])} · ${esc(b.location)}</div></td><td class="numeric">${num(remaining(state,b.id))} kg</td><td>${tag(b)}</td><td><button class="secondary small" data-do="inspect" data-id="${esc(b.id)}">Inspect</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching batches.</td></tr>'}</tbody></table></div>`;}
function inventory(){return head('Batch inventory','Know what is on hand, where it is stored and which batches need attention.')+`<section class="panel"><div class="panel-head"><h2>All stock</h2><label class="field">Search batches<input id="batch-search" value="${esc(search)}" placeholder="Batch, product or location"></label></div><div class="chips" role="group" aria-label="Filter by category">${[['','All'],...Object.entries(CATEGORIES)].map(([c,n])=>`<button type="button" class="chip ${catFilter===c?'on':''}" data-do="cat" data-id="${c}" aria-pressed="${catFilter===c}">${esc(n)} <span>${state.batches.filter(b=>!c||PRODUCTS[b.product].cat===c).length}</span></button>`).join('')}</div><div id="batch-list">${batchTable(filteredBatches())}</div></section><details class="panel" open><summary>Receive a new batch</summary><form id="batch-form" class="space"><div class="fields">${field('Batch ID','id','','text','required maxlength="80" placeholder="e.g. ST-C"')}${select('Product','product',productOpts('strawberries'))}${field('Received quantity (kg)','quantity',24,'number','min="0.01" max="100000" step="0.01" required')}${field('Location','location','','text','required maxlength="150"')}${field('Received at','received',local(state.asOf),'datetime-local','required')}${field('Date limit','limit',local(iso(Date.parse(state.asOf)+48*36e5)),'datetime-local','required')}${field('Initial temperature (°C)','temperature',4,'number','min="-40" max="80" step="0.1" required')}</div><p class="muted">Receipt captures one reading. Older batches need complete history before their estimates are available.</p><button class="primary">Add batch</button></form></details>`;}
function filteredBatches(){return state.batches.filter(b=>!catFilter||PRODUCTS[b.product].cat===catFilter).filter(b=>`${b.id} ${PRODUCTS[b.product].label} ${CATEGORIES[PRODUCTS[b.product].cat]} ${b.location}`.toLowerCase().includes(search.toLowerCase()));}
function twin(){const b=state.batches.find(b=>b.id===selectedBatch)||state.batches.slice().sort((a,b)=>quality(a,state.asOf).hours-quality(b,state.asOf).hours)[0];if(!b)return head('Expiry Twin','Receive a batch to start.')+'<a href="#inventory">Add inventory</a>';selectedBatch=b.id;const q=quality(b,state.asOf);return head('Read the batch, not just the date.','Temperature history changes the estimated quality window. Estimates never extend the date limit.')+`<div class="tabs">${state.batches.map(x=>`<button class="${x.id===b.id?'primary':'secondary'} small" data-do="select-batch" data-id="${esc(x.id)}">${esc(x.id)}</button>`).join('')}</div><div class="grid"><section class="panel"><div class="panel-head"><h2>${esc(b.id)} · ${esc(PRODUCTS[b.product].label)}</h2>${tag(b)}</div><div class="countdown">${q.blocked?'Review needed':num(q.hours)+' hours'}</div><p class="muted">Illustrative remaining quality window · ${num(remaining(state,b.id))} kg available</p><div id="twin-live">${twinLive(b)}</div><div class="note">${q.blocked?esc(q.reason)+'. Distribution proposals are blocked.':'Use this estimate for the demo only; staff checks govern actual release.'}</div><div class="table-wrap"><table><thead><tr><th>Observation</th><th class="numeric">Temperature</th></tr></thead><tbody>${b.sensors.slice().sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)).map(r=>`<tr><td>${esc(fmt(r.at))}${Date.parse(r.at)>Date.parse(state.asOf)?' (future; not modelled)':''}</td><td class="numeric">${num(r.temperature)} °C</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="${b.hold?'secondary':'danger-button'}" data-do="hold" data-id="${esc(b.id)}">${b.hold?'Release manual hold':'Place manual hold'}</button></div></section><section class="panel"><h2>Add temperature reading</h2><form id="sensor-form"><input type="hidden" name="batchId" value="${esc(b.id)}"><div class="fields">${field('Observation time','at',local(state.asOf),'datetime-local','required')}${field('Temperature (°C)','temperature',PRODUCTS[b.product].ref,'number','min="-40" max="80" step="0.1" required')}</div><p class="muted">A reading at an existing timestamp is rejected. Choose a new observation time within the model clock.</p><button class="primary">Record reading</button></form><details open><summary>Model assumptions</summary><p class="muted">Effective age integrates each reading until the next one, with Q10 = 2. Reference temperature: ${PRODUCTS[b.product].ref} °C; starting quality life: ${PRODUCTS[b.product].life} h. Modelled effective age: ${num(q.age)} h. Future storage is assumed at the reference temperature.</p><p class="muted">Receipt coverage is required. Gaps over 12 h or a latest reading over 6 h old trigger review. These are prototype settings, not validated safety limits.</p><p class="muted">Date limit: ${esc(fmt(b.limit))}. No microbiological safety prediction is made.</p></details></section></div>`;}
function forecast(){const s=state.settings,b=baseline(state,s.product,s.sector),rows=state.sales.filter(r=>r.product===s.product&&r.sector===s.sector).sort((a,b)=>b.date.localeCompare(a.date));return head('Demand before surplus.','Use recorded demand as a baseline, then convert covers or output targets into ingredient requirements.')+`<form id="context-form" class="panel"><div class="fields">${select('Business setting','sector',opts(SECTORS,s.sector))}${select('Product','product',productOpts(s.product))}</div><div class="actions"><button class="secondary">Set planning context</button></div></form><div class="grid equal"><section class="panel"><h2>Seven-day observed-day baseline</h2><div class="countdown">${b.kg===null?'No history':num(b.kg)+' kg/day'}</div><p class="muted">${b.days} distinct days with records in the seven complete calendar days before the model date. Missing days are not assumed to be zero.</p><button class="primary" data-do="baseline" ${b.kg===null?'disabled':''}>Use baseline for today and tomorrow</button><div class="note">Descriptive average only. No trained ML model, calibrated interval or guaranteed demand uplift.</div><h3 class="space">Demand history</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th class="numeric">Sales / usage kg</th></tr></thead><tbody>${rows.slice(0,14).map(r=>`<tr><td>${esc(r.date)}</td><td class="numeric">${num(r.kg)}</td></tr>`).join('')||'<tr><td colspan="2">No records for this setting.</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Recipe and yield calculator</h2><form id="recipe-form"><div class="fields">${field('Covers or output units','units',100,'number','min="0" max="100000" step="1" required')}${field('Ingredient kg per unit','perUnit',.2,'number','min="0" max="1000" step="0.001" required')}${field('Usable yield (%)','yield',90,'number','min="1" max="100" step="0.1" required')}</div><div class="actions"><button class="primary">Calculate and set today's demand</button></div></form><p class="muted">Input requirement = units × ingredient kg per unit ÷ yield fraction. Procurement for tomorrow stays independently editable.</p><h2 class="space">Record daily sales or usage</h2><form id="sales-form"><div class="fields">${field('Date','date',iso(Date.parse(state.asOf)-864e5).slice(0,10),'date','required')}${field('Quantity (kg)','kg',20,'number','min="0" max="100000" step="0.01" required')}</div><p class="muted">One daily total per product and business setting. Duplicate dates are rejected.</p><button class="secondary">Add daily total</button></form></section></div>`;}
function planner(){const s=state.settings,p=plan(state);return head('Plan with stock that will last.','Combine business requirements, batch quality and incoming stock into one allocation plan.')+`<form id="plan-form" class="panel"><div class="fields">${select('Business setting','sector',opts(SECTORS,s.sector))}${select('Product','product',productOpts(s.product))}${field('Today’s requirement (kg)','today',s.today,'number','min="0" max="100000" step="0.01" required')}${field('Tomorrow’s forecast (kg)','tomorrow',s.tomorrow,'number','min="0" max="100000" step="0.01" required')}${field('Need-by time from model clock (hours)','needIn',s.needIn,'number','min="0" max="24" step="0.5" required')}${field('Optional tomorrow buffer (kg)','buffer',s.buffer,'number','min="0" max="100000" step="0.01" required')}</div><div class="actions"><button class="primary">Recalculate plan</button><a href="#forecast" class="secondary">Use demand history</a></div></form><div class="kpis">${stat('Allocated today',num(p.allocated)+' kg','Unmet requirement: '+num(p.shortage)+' kg')}${stat('Eligible carryover',num(p.carry)+' kg','Still within quality window at next use')}${stat('Confirmed inbound',num(p.inbound)+' kg','Before tomorrow’s requirement')}${stat('Replenish tomorrow',num(p.order)+' kg','Forecast + buffer − carryover − inbound')}</div><section class="panel"><h2>Freshness-prioritised allocation</h2><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Quality</th><th class="numeric">On hand</th><th class="numeric">Use today</th><th class="numeric">Left</th></tr></thead><tbody>${p.list.map(b=>`<tr><td>${esc(b.id)}</td><td>${tag(b)}</td><td class="numeric">${num(b.left)} kg</td><td class="numeric">${num(b.used)} kg</td><td class="numeric">${num(b.after)} kg</td></tr>`).join('')}</tbody></table></div><div class="note">${num(p.review)} kg needs earlier intervention; ${num(p.held)} kg is held. Allocations are proposals, not stock movements. Incoming receipts are counted only for tomorrow; record receipt as a batch and remove its inbound entry to avoid double counting.</div><a href="#actions" class="primary">Compare interventions ↗</a></section><details class="panel" open><summary>Confirmed incoming stock</summary><form id="inbound-form" class="space"><div class="fields">${select('Product','product',productOpts(s.product))}${field('Quantity (kg)','kg',10,'number','min="0.01" max="100000" step="0.01" required')}${field('Expected arrival','arrival',local(iso(Date.parse(state.asOf)+24*36e5)),'datetime-local','required')}${field('Date limit','limit',local(iso(Date.parse(state.asOf)+96*36e5)),'datetime-local','required')}</div><label class="check"><input name="confirmed" type="checkbox" required>Supplier has confirmed this incoming quantity</label><button class="secondary">Add inbound stock</button></form><div class="table-wrap space"><table><thead><tr><th>Product</th><th>Arrival</th><th>Quantity</th><th></th></tr></thead><tbody>${state.inbound.map(r=>`<tr><td>${esc(PRODUCTS[r.product].label)}</td><td>${esc(fmt(r.arrival))}</td><td>${num(r.kg)} kg</td><td><button class="secondary small" data-do="remove-inbound" data-id="${r.id}">Remove</button></td></tr>`).join('')}</tbody></table></div></details>`;}
function actions(){const s=state.settings,names={baseline:'Ordinary rotation',rotate:'Use earliest quality first',markdown:'Markdown scenario',transfer:'Transfer scenario'};return head('Turn the forecast into action.','Compare illustrative scenarios, then propose a batch-level decision for staff review.')+`<div class="note">${esc(PRODUCTS[s.product].label)} · ${esc(SECTORS[s.sector])} · ${num(s.today)} kg demand over 24 hours. Scenario sales are spread hourly; the stock planner instead uses one specified need-by time.</div><div class="scenarios">${(()=>{const runs=Object.keys(names).map(m=>simulate(state,m)),low=Math.min(...runs.map(r=>r.atRisk)),base=runs[0].atRisk;return runs.map(r=>{const mode=r.mode,best=r.atRisk<=low+1e-9&&r.atRisk<base-1e-9;return `<section class="scenario ${best?'best':''}"><span class="tag">${names[mode]}${best?' · lowest waste risk':''}</span><b>${num(r.atRisk)} kg</b><div class="muted">At risk of waste before the next use</div><p class="muted">${mode==='baseline'?'Reference case':`${num(Math.max(0,base-r.atRisk))} kg less at risk · ≈${num(Math.max(0,base-r.atRisk)*s.factor)} kg CO₂-e`}<br>${num(r.unresolved)} kg unallocated usable stock<br>${num(r.sold)} kg sold / used<br>${num(r.transferred)} kg modelled transfer<br>A$${num(r.revenue,2)} sales value<br>${num(r.held)} kg excluded on hold</p></section>`;}).join('');})()}</div><details class="panel" open><summary>Scenario assumptions</summary><form id="scenario-form" class="space"><div class="fields">${field('Unit sales price (A$/kg)','price',s.price,'number','min="0" max="10000" step="0.01" required')}${field('Markdown (%)','markdown',s.markdown,'number','min="0" max="100" required')}${field('Assumed demand uplift (%)','uplift',s.uplift,'number','min="0" max="300" required')}${field('Recipient capacity (kg)','capacity',s.capacity,'number','min="0" max="100000" step="0.01" required')}${field('Collection / travel lead (h)','travel',s.travel,'number','min="0" max="168" step="0.5" required')}${field('Destination','destination',s.destination,'text','maxlength="200"')}${field('Landfill factor (kg CO₂-e / kg food)','factor',s.factor,'number','min="0" max="20" step="0.01" required')}</div><div class="actions"><button class="secondary">Update assumptions</button></div></form><p class="muted">At risk = usable stock left after the 24-hour period in batches whose quality window ends before the next need-by time (24 h + ${num(s.needIn)} h). CO₂-e uses the landfill factor above, default from ${esc(CLIMATE.factorSource)}. Demand uplift is an assumption, not a measured effect. Transfer is modelled after the 24-hour sales period and requires enough remaining quality time for collection. Revenue excludes costs. No scenario amount is recorded as actual waste prevented.</p></details><div class="grid equal"><section class="panel" id="propose"><h2>Propose a batch action</h2>${prefill?`<div class="note">Prefilled from the Rescue ladder: ${esc(prefill.batchId)} · ${esc(ACTION_LABEL[prefill.action])}. Review before submitting.</div>`:''}<form id="decision-form"><div class="fields">${select('Batch','batchId',batchOptions(prefill?.batchId))}${select('Action','action',opts({sell:'Sell',use:'Use in preparation / production',donate:'Donate',transfer:'Transfer',inspect:'Hold for inspection',discard:'Discard'},prefill?.action||'sell'))}${field('Quantity (kg)','kg',prefill?.kg??5,'number','min="0.01" max="100000" step="0.01" required')}${field('Destination for transfer / donation','destination',prefill?.destination||'','text','maxlength="200"')}<label class="field wide">Reason or operational note<textarea name="note" maxlength="1500" required>${esc(prefill?.why||'')}</textarea></label></div><button class="primary">Create proposal</button></form></section><section class="panel"><h2>Review queue</h2>${state.decisions.filter(d=>d.status==='proposed').map(d=>`<form class="approval-form" data-id="${d.id}"><div class="flow-row"><span class="step">↗</span><div><strong>${esc(d.batchId)} · ${esc(d.action)} ${num(d.kg)} kg</strong><p>${esc(d.note)}${d.destination?' · '+esc(d.destination):''}</p><span class="tag ${d.revision!==state.revision?'warn':''}">${d.revision!==state.revision?'Stale · create a fresh proposal':'Ready for review'}</span></div></div>${field('Reviewer name','reviewer','','text','maxlength="150" required')}<label class="check"><input type="checkbox" name="checked" required>Quality, date and operational checks complete; recipient / transport confirmed where relevant</label><div class="actions"><button class="primary small" ${d.revision!==state.revision?'disabled':''}>Approve</button><button type="button" class="secondary small" data-do="cancel" data-id="${d.id}">Cancel proposal</button></div></form>`).join('')||'<div class="empty">No proposals awaiting review.</div>'}<p class="muted">Reviewer names are labels in this local demo, not authenticated identities.</p></section></div>`;}
function outcomes(){const eligible=state.decisions.filter(d=>d.status==='approved'&&d.action!=='inspect'&&d.revision===state.revision);const total=kind=>state.outcomes.filter(o=>kind.includes(o.action)).reduce((v,o)=>v+o.kg,0);return head('Evidence after the action.','Record what happened. Keep operational outcomes separate from modelled surplus and climate claims.',`<button class="secondary" data-do="export-csv">Export outcomes CSV</button>`)+`<div class="kpis">${stat('Recorded sales / use',num(total(['sell','use']))+' kg','Entered observations')}${stat('Recorded donations',num(total(['donate']))+' kg','Receipt evidence required')}${stat('Recorded transfers',num(total(['transfer']))+' kg','Destination use not yet verified')}${stat('Recorded discard',num(total(['discard']))+' kg','Observed stock disposition')}</div><div class="grid equal"><section class="panel"><h2>Record an approved outcome</h2>${eligible.length?`<form id="outcome-form"><div class="fields wide">${select('Approved stock movement','decisionId',eligible.map(d=>`<option value="${d.id}">${esc(d.batchId)} · ${esc(d.action)} · up to ${num(d.kg)} kg</option>`).join(''))}${field('Actual quantity (kg)','kg',1,'number','min="0.01" max="100000" step="0.01" required')}<label class="field wide">Evidence or observation reference<textarea name="evidence" required maxlength="1500" placeholder="Receipt number, sales report or observation note"></textarea></label></div><div class="note">Each approval allows one outcome entry, including a partial fulfilment. Unused approved quantity returns to the planning process. This stock change invalidates other approvals.</div><button class="primary">Record outcome and update stock</button></form>`:'<div class="empty">Approve a current stock movement under Actions &amp; approvals first.</div>'}</section><section class="panel"><h2>What these figures establish</h2><div class="flow-row"><span class="step">1</span><div><strong>Recorded movement</strong><p>Stock sold, used, donated, transferred or discarded, entered by the user.</p></div></div><div class="flow-row"><span class="step">2</span><div><strong>Evidence reference</strong><p>A traceable note; the app does not independently verify receipts.</p></div></div><div class="flow-row"><span class="step">3</span><div><strong>No automatic climate credit</strong><p>Transfers are not assumed consumed. Recorded figures carry no avoided-emissions credit; the Overview Climate lens is a separately labelled model.</p></div></div></section></div><section class="panel space"><h2>Outcome ledger</h2><div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Batch</th><th>Action</th><th class="numeric">kg</th><th>Evidence</th></tr></thead><tbody>${state.outcomes.slice().reverse().map(o=>`<tr><td>${esc(fmt(o.at))}</td><td>${esc(o.batchId)}</td><td>${esc(o.action)}</td><td class="numeric">${num(o.kg)}</td><td>${esc(o.evidence)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No outcomes entered.</td></tr>'}</tbody></table></div></section><details class="panel"><summary>All decision states</summary><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Action</th><th>Status</th><th>Reviewer</th></tr></thead><tbody>${state.decisions.map(d=>`<tr><td>${esc(d.batchId)}</td><td>${esc(d.action)}</td><td>${esc(d.status)}${['proposed','approved'].includes(d.status)&&d.revision!==state.revision?' · stale':''}</td><td>${esc(d.reviewer||'—')}</td></tr>`).join('')}</tbody></table></div></details>`;}
function handover(){return head('Everything, kept together.','The build split, idea provenance, operating assumptions and portable workspace backup.')+`<div class="grid equal"><section class="panel"><h2>The integrated concept</h2><div class="credit"><strong>Madhumitha Challa</strong><p class="muted">Waste prevention through demand and stock planning across retail, hospitality and food production.</p></div><div class="credit"><strong>Abhishek</strong><p class="muted">Temperature-history Expiry Twin for estimated batch freshness and priority.</p></div><div class="credit"><strong>Vijay · read and retained separately</strong><p class="muted">Rot Clock: household food countdowns, rescue meals, rewards and savings for students and share-houses. Not added to this business-app scope. Proposed methane estimates require separate evidence.</p></div><a class="secondary" href="PROJECT.md" download>Download project handover</a></section><section class="panel"><h2>Backup and restore</h2><p class="muted">Records are saved in this browser only. Other devices and teammates do not share this data. Export JSON before clearing browser storage or moving devices.</p><div class="actions"><button class="primary" data-do="backup">Export workspace JSON</button><button class="secondary" data-do="export-csv">Export outcomes CSV</button></div><form id="restore-form" class="space"><label class="field">Choose a CliMaze JSON backup<input type="file" name="backup" accept="application/json,.json" required></label><label class="check"><input type="checkbox" required>I exported my current data and want to replace this browser’s workspace</label><button class="secondary">Validate and restore</button></form><details><summary>Model clock and demo reset</summary><form id="clock-form" class="space">${field('Model clock (local time)','asOf',local(state.asOf),'datetime-local','required')}<div class="actions"><button class="secondary">Update clock</button></div></form><p class="muted">Clock changes recalculate freshness and invalidate approvals. Audit timestamps use actual entry time.</p><form id="reset-form"><label class="check"><input name="confirm" type="checkbox" required>I exported anything needed and want to restore synthetic starter records</label><button class="danger-button">Reset this browser workspace</button></form></details></section></div><section class="panel space"><div class="panel-head"><h2>${EPICS.length} implemented MVP epics</h2><span class="tag">Proposed ownership</span></div>${EPICS.map(e=>`<div class="epic"><span class="tag">${e[0]}</span><div><strong>${e[1]}</strong><p>${e[2]}</p><span class="tiny">Suggested delivery owners: ${e[3]} · team agreement required</span></div></div>`).join('')}<div class="note">Implemented: local workflows with transparent rules. Production gates remain real-data model validation, shared database, authenticated roles, partner integrations and security review. These are not represented as finished production features.</div></section><details class="panel"><summary>Audit history</summary>${state.audit.map(a=>`<div class="flow-row"><span class="step">·</span><div><strong>${esc(a.action)}</strong><p>${esc(a.detail)} · ${esc(fmt(a.at))}</p></div></div>`).join('')||'<p class="muted">No changes recorded yet.</p>'}</details>`;}
function render(){view=location.hash.slice(1)||'overview';if(!paths.some(p=>p[0]===view))view='overview';$('breadcrumb').textContent=paths.find(p=>p[0]===view)[1].toUpperCase();$('nav').innerHTML=paths.map((p,i)=>`<a href="#${p[0]}" class="${p[0]===view?'active':''}" ${p[0]===view?'aria-current="page"':''}><span class="nav-num">${String(i+1).padStart(2,'0')}</span>${p[1]}</a>`).join('');const pages={overview,about,report,inventory,twin,forecast,planner,actions,outcomes,handover};$('main').innerHTML=(storageError?`<div class="note warn" role="alert">${esc(storageError)} <button class="secondary small" data-do="raw-backup">Export original stored data</button> <a href="#handover">Recovery controls</a></div>`:'')+pages[view]();if(view!=='actions')prefill=null;if(tourStep>=0&&TOUR[tourStep][0]!==view)tourStep=TOUR.findIndex(t=>t[0]===view);tour();}
$('backup-top').addEventListener('click',backup);window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
$('main').addEventListener('input',e=>{if(e.target.id==='batch-search'){search=e.target.value;$('batch-list').innerHTML=batchTable(filteredBatches());}if(e.target.id==='whatif'){const b=state.batches.find(b=>b.id===selectedBatch);if(!b)return;whatIf=Number(e.target.value);const live=$('twin-live'),pos=e.target.value;live.innerHTML=twinLive(b);const r=$('whatif');r.value=pos;r.focus();}});
$('tour-start')?.addEventListener('click',()=>goTour(0));
function textSize(v){document.documentElement?.style?.setProperty('--text-scale',v);document.querySelectorAll?.('#text-size [data-size]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.size===String(v))));try{localStorage.setItem('shelfshift-text-scale',v);}catch{}}
try{textSize(localStorage.getItem('shelfshift-text-scale')||'1.12');}catch{textSize('1.12');}
$('text-size')?.addEventListener('click',e=>{const b=e.target.closest?.('[data-size]');if(b)textSize(b.dataset.size);});$('tour')?.addEventListener('click',e=>{const t=e.target.closest('[data-tour]');if(!t)return;const a=t.dataset.tour;goTour(a==='close'?-1:a==='back'?tourStep-1:tourStep+1>=TOUR.length?-1:tourStep+1);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tourStep>=0)goTour(-1);});
$('main').addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b)return;try{const id=b.dataset.id;switch(b.dataset.do){case'inspect':selectedBatch=id;location.hash='twin';if(view==='twin')render();break;case'cat':catFilter=id;render();break;case'print-report':window.print();break;case'download-report':download('ShelfShift_Impact_Report.html',reportDocument(),'text/html');break;case'select-batch':selectedBatch=id;whatIf=null;render();break;case'prefill':{const x=rescue(state)[Number(b.dataset.i)];if(x){prefill=x;location.hash='actions';if(view==='actions')render();}break;}case'hold':commit(s=>{const r=s.batches.find(b=>b.id===id);r.hold=!r.hold;},'Manual hold updated',true);break;case'baseline':{const f=baseline(state,state.settings.product,state.settings.sector);if(f.kg===null)throw Error('No history.');commit(s=>{s.settings.today=s.settings.tomorrow=Math.round(f.kg*100)/100;},'Baseline applied',true);break;}case'remove-inbound':commit(s=>s.inbound=s.inbound.filter(r=>r.id!==id),'Inbound entry removed',true);break;case'cancel':commit(s=>{const d=s.decisions.find(d=>d.id===id);d.status='cancelled';addAudit(s,'Proposal cancelled',d.batchId);},'Proposal cancelled');break;case'backup':backup();break;case'raw-backup':download('CliMaze_original_recovery.json',localStorage.getItem(KEY)||'','application/json');break;case'export-csv':download('CliMaze_outcomes.csv',csv([['Recorded time','Batch','Action','kg','Evidence'],...state.outcomes.map(o=>[o.at,o.batchId,o.action,o.kg,o.evidence])]),'text/csv');break;}}catch(e){toast(e.message,true);}});
$('main').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),v=Object.fromEntries(fd.entries()),n=k=>Number(v[k]);try{switch(f.id){case'batch-form':commit(s=>{const id=v.id.trim();if(s.batches.some(b=>b.id===id))throw Error('This batch ID already exists.');const received=toISO(v.received),limit=toISO(v.limit);if(Date.parse(received)>Date.parse(s.asOf))throw Error('Receipt cannot be later than the model clock.');if(Date.parse(limit)<=Date.parse(received))throw Error('Date limit must follow receipt.');s.batches.push({id,product:v.product,quantity:n('quantity'),received,limit,location:v.location.trim(),hold:false,sensors:[{at:received,temperature:n('temperature')}]});},'Batch received',true);break;case'sensor-form':commit(s=>{const b=s.batches.find(b=>b.id===v.batchId),at=toISO(v.at);if(Date.parse(at)<Date.parse(b.received)||Date.parse(at)>Date.parse(s.asOf))throw Error('Reading must fall between receipt and model clock.');if(b.sensors.some(r=>r.at===at))throw Error('A reading already exists at that timestamp.');b.sensors.push({at,temperature:n('temperature')});},'Temperature reading recorded',true);break;case'context-form':commit(s=>{s.settings.sector=v.sector;s.settings.product=v.product;s.settings.price=PRODUCTS[v.product].price;},'Planning context changed',true);break;case'recipe-form':{const kg=ingredientNeed(n('units'),n('perUnit'),n('yield'));commit(s=>s.settings.today=Math.round(kg*100)/100,'Ingredient need set to '+num(kg)+' kg',true);break;}case'sales-form':commit(s=>{if(v.date>=s.asOf.slice(0,10))throw Error('Use a completed day before the model date.');if(s.sales.some(r=>r.date===v.date&&r.product===s.settings.product&&r.sector===s.settings.sector))throw Error('A daily total already exists for this product and setting.');s.sales.push({id:uid(),date:v.date,product:s.settings.product,sector:s.settings.sector,kg:n('kg')});},'Daily demand recorded',true);break;case'plan-form':commit(s=>{s.settings={...s.settings,sector:v.sector,product:v.product,today:n('today'),tomorrow:n('tomorrow'),needIn:n('needIn'),buffer:n('buffer')};},'Stock plan recalculated',true);break;case'inbound-form':commit(s=>{const arrival=toISO(v.arrival),limit=toISO(v.limit);if(Date.parse(arrival)<Date.parse(s.asOf)||Date.parse(limit)<=Date.parse(arrival))throw Error('Arrival must be at or after the model clock; date limit must follow arrival.');s.inbound.push({id:uid(),product:v.product,kg:n('kg'),arrival,limit,confirmed:fd.has('confirmed')});},'Confirmed inbound stock added',true);break;case'scenario-form':commit(s=>{for(const key of ['price','markdown','uplift','capacity','travel','factor'])s.settings[key]=n(key);s.settings.destination=v.destination.trim();},'Scenario assumptions updated',true);break;case'decision-form':commit(s=>propose(s,{...v,kg:n('kg')}),'Decision proposed');prefill=null;render();break;case'outcome-form':commit(s=>recordOutcome(s,{decisionId:v.decisionId,kg:n('kg'),evidence:v.evidence}),'Outcome recorded');break;case'clock-form':commit(s=>s.asOf=toISO(v.asOf),'Model clock updated',true);break;case'restore-form':{const file=fd.get('backup');if(file.size>5*1024*1024)throw Error('Backup must be under 5 MB.');const restored=validateState(JSON.parse(await file.text()));addAudit(restored,'Backup restored','Validated user-selected JSON backup');localStorage.setItem(KEY,JSON.stringify(restored));state=restored;storageError='';render();toast('Backup restored');break;}case'reset-form':{const next=seed();localStorage.setItem(KEY,JSON.stringify(next));state=next;storageError='';render();toast('Synthetic workspace restored');break;}default:if(f.classList.contains('approval-form'))commit(s=>approve(s,f.dataset.id,v.reviewer),'Decision approved');}}catch(e){toast(e.message||'Unable to save this change.',true);}});
render();
